function fgParseFolded(text){
  var lines=String(text||'').split(/\n+/), rows=[], bad=0;
  for(var i=0;i<lines.length;i++){
    var l=lines[i].trim();
    if(!l || l.charAt(0)==='#') continue;
    var m=l.match(/^(.+?)\s+(\d+(?:\.\d+)?)$/);
    if(!m){ bad++; continue; }
    var frames=m[1].split(';').map(function(s){ return s.trim(); }).filter(function(s){ return s!==''; });
    if(!frames.length){ bad++; continue; }
    rows.push({ frames:frames, value:parseFloat(m[2]) });
  }
  if(!rows.length) return { error:'未解析到有效的折叠栈行（格式：a;b;c 123）', bad:bad };
  return { error:null, rows:rows, bad:bad };
}
function fgBuild(rows){
  var root={ name:'root', value:0, children:{}, depth:0 };
  for(var i=0;i<rows.length;i++){
    var node=root, fr=rows[i].frames;
    root.value += rows[i].value;
    for(var j=0;j<fr.length;j++){
      if(!node.children[fr[j]]) node.children[fr[j]]={ name:fr[j], value:0, children:{}, depth:j+1 };
      node = node.children[fr[j]];
      node.value += rows[i].value;
    }
    node.self = (node.self||0) + rows[i].value;
  }
  return root;
}
function fgFlatten(root){
  var out=[];
  function walk(node, x){
    out.push({ name:node.name, value:node.value, self:node.self||0, depth:node.depth, x:x });
    var keys=Object.keys(node.children).sort(function(a,b){
      var d=node.children[b].value-node.children[a].value;
      return d!==0 ? d : (a<b?-1:1);
    });
    var cx=x;
    for(var i=0;i<keys.length;i++){ walk(node.children[keys[i]], cx); cx += node.children[keys[i]].value; }
  }
  walk(root, 0);
  return out;
}
function fgSelfTop(flat, k){
  var arr=flat.filter(function(f){ return f.depth>0 && f.self>0; })
              .sort(function(a,b){ return b.self-a.self || (a.name<b.name?-1:1); });
  return arr.slice(0, k||5);
}
function fgHotPath(root){
  var path=[], node=root;
  while(true){
    var keys=Object.keys(node.children);
    if(!keys.length) break;
    var best=keys[0];
    for(var i=1;i<keys.length;i++) if(node.children[keys[i]].value>node.children[best].value) best=keys[i];
    node=node.children[best]; path.push({ name:node.name, value:node.value });
  }
  return path;
}
function fgStats(root, flat){
  var maxDepth=0, leaves=0;
  for(var i=0;i<flat.length;i++){
    if(flat[i].depth>maxDepth) maxDepth=flat[i].depth;
    if(flat[i].self>0) leaves++;
  }
  return { total:root.value, frames:flat.length-1, maxDepth:maxDepth, leaves:leaves };
}
function fgColor(name){
  var h=0;
  for(var i=0;i<name.length;i++) h=(h*31+name.charCodeAt(i))>>>0;
  var hue = 15 + (h % 45);
  var sat = 62 + (h>>8) % 20;
  var lig = 44 + (h>>16) % 14;
  return 'hsl('+hue+','+sat+'%,'+lig+'%)';
}
function fgPercent(v, total){
  if(!total) return '0.00%';
  return (v/total*100).toFixed(2)+'%';
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { fgParseFolded:fgParseFolded, fgBuild:fgBuild, fgFlatten:fgFlatten,
    fgSelfTop:fgSelfTop, fgHotPath:fgHotPath, fgStats:fgStats, fgColor:fgColor, fgPercent:fgPercent };
}
if (typeof window !== 'undefined') {
  window.FlamegraphForgePure = { fgParseFolded:fgParseFolded, fgBuild:fgBuild, fgFlatten:fgFlatten,
    fgSelfTop:fgSelfTop, fgHotPath:fgHotPath, fgStats:fgStats, fgColor:fgColor, fgPercent:fgPercent };
}
